let baseMode = null;
let baseByName = {}; // name -> Variable (resolved/imported)
let libKeyByName = null;
async function collectionVars(col) {
    const list = (await Promise.all(col.variableIds.map((id) => figma.variables.getVariableByIdAsync(id)))).filter((v) => Boolean(v));
    const byName = {}, byId = {};
    for (const v of list) {
        byName[v.name] = v;
        byId[v.id] = v;
    }
    return { list, byName, byId };
}
