        baseMode,
        count: String(p.vars.byName['Count'].valuesByMode[p.mode] || '4'),
        source: String(p.vars.byName['Source'].valuesByMode[p.mode] || ''),
        roles, slots, favourites, presets: Object.keys(presets),
